@import url('https://fonts.googleapis.com/css2?family=Questrial&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Ableton DNA — flat color blocks, geometric type, zero decoration, Bauhaus pop */
.theme-ableton-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.973 0 0);
  --surface-2: oklch(0.946 0 0);
  --fg: oklch(0.145 0 0);
  --fg-muted: oklch(0.510 0 0);
  --accent: oklch(0.637 0.252 15.4);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.775 0.138 182.9);
  --line: oklch(0.145 0 0);
  --success: oklch(0.775 0.138 182.9);
  --warning: oklch(0.875 0.166 91.5);
  --danger: oklch(0.584 0.188 36.7);
  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;
  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
  --glow: 0 0 0 2px var(--accent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Questrial", sans-serif;
  --font-body: "Questrial", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.05em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-ableton-dna h1,
.theme-ableton-dna h2,
.theme-ableton-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-ableton-dna { --font-ui: var(--font-display); }
.theme-ableton-dna h1 { font-weight: 400; }
.theme-ableton-dna button { transition: none; }
.theme-ableton-dna button:hover { background: var(--fg); color: var(--bg); }

/* depth */
.theme-ableton-dna table { border: 1px solid var(--fg); border-collapse: collapse; }
.theme-ableton-dna th, .theme-ableton-dna td { border: 1px solid var(--fg); }
.theme-ableton-dna thead th { background: var(--warning); color: var(--fg); font-weight: 400; }
.theme-ableton-dna tbody tr:hover { background: var(--surface); }
.theme-ableton-dna a { color: var(--fg); text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 2px; }
.theme-ableton-dna a:hover { background: var(--warning); text-decoration: none; }
.theme-ableton-dna input, .theme-ableton-dna select, .theme-ableton-dna textarea { border: 1px solid var(--fg); border-radius: 0; background: var(--bg); transition: none; }
.theme-ableton-dna input:focus-visible, .theme-ableton-dna select:focus-visible, .theme-ableton-dna textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 0; box-shadow: none; }
.theme-ableton-dna kbd { border: 1px solid var(--fg); border-radius: 0; padding: 0.1em 0.4em; font-size: 0.8em; background: var(--surface-2); }
.theme-ableton-dna ::selection { background: var(--warning); color: var(--fg); }
.theme-ableton-dna ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-ableton-dna ::-webkit-scrollbar-track { background: var(--surface); }
.theme-ableton-dna ::-webkit-scrollbar-thumb { background: var(--fg); border-radius: 0; }
.theme-ableton-dna button:active { background: var(--accent); color: var(--accent-fg); }
.theme-ableton-dna .label-caps { background: var(--fg); color: var(--bg); padding: 0.1em 0.5em; }
.theme-ableton-dna .themed-border { border-color: var(--fg); box-shadow: 8px 8px 0 var(--accent-2); }

/* alt mode: Live dark set — mid-gray console, flat as ever */
.theme-ableton-dna.alt-mode {
  --bg: oklch(0.280 0 0);
  --surface: oklch(0.330 0 0);
  --surface-2: oklch(0.380 0 0);
  --fg: oklch(0.935 0 0);
  --fg-muted: oklch(0.720 0 0);
  --line: oklch(0.935 0 0);
  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
}
.theme-ableton-dna.alt-mode table,
.theme-ableton-dna.alt-mode th,
.theme-ableton-dna.alt-mode td { border-color: var(--fg); }
.theme-ableton-dna.alt-mode input, .theme-ableton-dna.alt-mode select, .theme-ableton-dna.alt-mode textarea { background: var(--surface); border-color: var(--fg); }
.theme-ableton-dna.alt-mode .label-caps { background: var(--fg); color: var(--bg); }
.theme-ableton-dna.alt-mode ::-webkit-scrollbar-track { background: var(--surface); }
.theme-ableton-dna.alt-mode thead th { color: oklch(0.145 0 0); }
.theme-ableton-dna.alt-mode a:hover { color: oklch(0.145 0 0); }
.theme-ableton-dna.alt-mode ::selection { background: var(--warning); color: oklch(0.145 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
